package com.mineclone;

import com.mineclone.world.*;
import com.mineclone.world.entity.*;
import com.mineclone.world.gen.*;
import com.mineclone.world.damage.*;
import com.mineclone.sim.*;
import com.mineclone.net.*;
import com.mineclone.item.*;
import com.mineclone.item.loot.*;
import com.mineclone.save.*;
import com.mineclone.data.*;
import java.util.*;
import java.nio.file.*;
import org.joml.Vector3f;

/** Entity lifecycle scenarios exercise persistence, birth, stable wire IDs and finite initial generation. */
final class EntityLifecycleTests {
    static void runAll(TestMain.Runner r){
        r.run("persistent entities round trip with identity health age and breeding clocks",EntityLifecycleTests::codec);
        r.run("chunk adoption is once and a herd survives unloading 500 blocks away",EntityLifecycleTests::unload);
        r.run("stable varlong ids and baby age survive snapshots without mirror recreation",EntityLifecycleTests::wire);
        r.run("two fed cows produce one calf and cannot breed again during cooldown",EntityLifecycleTests::breeding);
        r.run("feeding babies advances age without love and animals follow food holders",EntityLifecycleTests::feeding);
        r.run("baby loot is empty and leather and bow string are reachable",EntityLifecycleTests::loot);
        r.run("initial herds are deterministic and restored empty chunks never respawn them",EntityLifecycleTests::generation);
        r.run("a dedicated server saves and restores the same herd after stop",EntityLifecycleTests::serverRestart);
    }
    static void check(boolean value,String reason){if(!value)throw new AssertionError(reason);}
    static Mob cow(long id,float x){var m=new Mob(MobType.COW,x,41,6.5f,new Random(id));m.id=id;return m;}
    static WorldSession session(World w,WorldClock clock,EntityStore store){return new WorldSession(w,clock,new MobSpawner(1),store,new Participants(),new WorldSession.Host(){public Vector3f mobFocus(){return new Vector3f(500,70,500);}public boolean spawnMobs(){return false;}},WorldEvents.NONE);}
    static void codec(){var a=cow(9000000000L,6.5f);a.age=-850;a.health=3;a.love=22;a.loveCooldown=290;var bytes=EntityPersistence.encode(List.of(a));var b=EntityPersistence.decode(bytes).get(0);check(b.id==a.id&&b.age==a.age&&b.health==a.health&&b.love==a.love&&b.loveCooldown==a.loveCooldown,"entity fields");var clock=new WorldClock();clock.observeEntityId(b.id);long next=WorldClock.fromSaved(0,clock.encode()).nextEntityId();check(next==a.id+1,"counter restore");for(byte[] invalid:List.of(new byte[]{9},Arrays.copyOf(bytes,bytes.length-1),new byte[140000]))try{EntityPersistence.decode(invalid);throw new AssertionError("corrupt accepted");}catch(IllegalArgumentException expected){} }
    static void unload(){var w=FarmingTests.blank();var clock=new WorldClock();var store=new EntityStore();var session=session(w,clock,store);var c=w.getChunkIfExists(0,0);session.adoptChunkItems(c);store.mobs.add(cow(77,6.5f));var hostile=new Mob(MobType.ZOMBIE,5,41,5,new Random(1));hostile.id=78;store.mobs.add(hostile);var snap=session.snapshotChunk(c);check(EntityPersistence.decode(snap.extra.get("entities")).size()==1,"hostile persisted");session.forgetChunk(c);check(store.mobs.isEmpty(),"unload left entities");var loaded=new Chunk(0,0);loaded.restore(snap.blocks,snap.meta);loaded.restoreExtraSections(snap.extra);loaded.restoredFromSave=true;session.adoptChunkItems(loaded);check(store.mobs.size()==1&&store.mobs.get(0).id==77,"herd return changed identity");session.adoptChunkItems(loaded);check(store.mobs.size()==1,"duplicate adoption");store.mobs.clear();session.adoptChunkItems(loaded);check(store.mobs.isEmpty(),"dead animal revived from stale snapshot");}
    static void wire(){for(long id:new long[]{1,127,128,1L<<40,Long.MAX_VALUE}){var p=new PacketBuf().varLong(id);var read=PacketBuf.reading(p.toBytes());check(read.readVarLong()==id&&!read.truncated(),"varlong "+id);}var invalid=PacketBuf.reading(new byte[]{(byte)128,(byte)128,(byte)128,(byte)128,(byte)128,(byte)128,(byte)128,(byte)128,(byte)128,0});invalid.readVarLong();check(invalid.truncated(),"oversized varlong");var m=cow(1L<<40,6);m.age=-987;var shot=MobSnapshot.capture(m.id,m);var p=new PacketBuf();shot.write(p);var restored=MobSnapshot.read(PacketBuf.reading(p.toBytes()));check(restored.valid()&&restored.age()==m.age&&restored.id()==m.id,"snapshot age/id");var mirror=cow(m.id,0);var remote=new RemoteMob(mirror);remote.accept(restored);remote.update(.1f);check(mirror.age==m.age,"baby mirror age");}
    static void breeding(){var w=FarmingTests.blank();var mobs=new ArrayList<Mob>(List.of(cow(1,6),cow(2,7)));var food=ItemStack.of("wheat",3);for(var m:mobs)check(Breeding.feed(m,food,GameMode.SURVIVAL),"feed cow");check(food.count==1,"feed conservation");var b=new Breeding();b.tick(w,mobs,new Participants(),.05f,()->3);check(mobs.get(0).foodTarget!=null&&mobs.get(1).foodTarget!=null,"both parents must approach");var clock=new WorldClock();clock.observeEntityId(2);for(int i=0;i<100;i++)b.tick(w,mobs,new Participants(),.05f,clock::nextEntityId);check(mobs.get(2).id==3,"birth must reserve exactly one identity");check(mobs.size()==3&&mobs.get(2).baby()&&mobs.get(2).persistent,"calf not born");check(mobs.get(0).loveCooldown==300&&!Breeding.feed(mobs.get(0),food,GameMode.SURVIVAL),"parent cooldown");check(food.count==1,"denied feed consumed");for(int i=0;i<100;i++)b.tick(w,mobs,new Participants(),.05f,clock::nextEntityId);check(mobs.size()==3,"duplicate birth");}
    static void feeding(){var w=FarmingTests.blank();var baby=cow(1,6);baby.age=-1200;var food=ItemStack.of("wheat",2);check(Breeding.feed(baby,food,GameMode.SURVIVAL)&&baby.age==-1080&&baby.love==0,"baby love/age");var adult=cow(2,7);var player=new com.mineclone.game.Player();player.position.set(12,41,6);var participant=new com.mineclone.game.LocalParticipant(player,()->1);participant.held=()->food;var participants=new Participants();participants.put(participant);new Breeding().tick(w,new ArrayList<>(List.of(baby,adult)),participants,.05f,()->3);check(adult.foodTarget!=null&&adult.foodTarget.x==12,"temptation missing");float start=baby.growthScale();baby.age=-.001f;check(Math.abs(baby.growthScale()-1)<.001&&start<1,"growth discontinuity");}
    static void loot(){var random=new Random(4);for(var type:MobType.values()){var context=new LootContext(1,0,40,0,null,true,GameMode.SURVIVAL,random,0,false);for(int i=0;i<20;i++)check(Items.get().loot().entityDrops(type,context).isEmpty(),"baby loot "+type);}int leather=0,beef=0;for(int i=0;i<300;i++)for(var drop:Items.get().loot().entityDrops(MobType.COW,new LootContext(1,0,40,0,null,true,GameMode.SURVIVAL,random))){if(drop.item.id.path().equals("leather"))leather+=drop.count;if(drop.item.id.path().equals("beef"))beef+=drop.count;}check(leather>100&&beef>400&&beef<800,"cow data distribution");check(Items.get().tags().members(com.mineclone.data.ResourceId.of("mineclone:bowstring")).contains(Items.get().require("string")),"string tag");}
    static void generation(){var a=new World(123,GenPolicy.fixed(WorldGenVersion.V2));var b=new World(123,GenPolicy.fixed(WorldGenVersion.V2));int count=0;for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++){var ca=a.getChunk(x,z);var cb=b.getChunk(x,z);var first=SpawnTable.get().initialHerd(a,ca);var second=SpawnTable.get().initialHerd(b,cb);check(first.size()==second.size(),"generation count");for(int i=0;i<first.size();i++)check(first.get(i).type==second.get(i).type&&first.get(i).position.equals(second.get(i).position),"generation coordinates");count+=first.size();}check(count>=4,"new world has no herds");var stored=a.getChunk(0,0);stored.restoredFromSave=true;var store=new EntityStore();session(a,new WorldClock(),store).adoptChunkItems(stored);check(store.mobs.isEmpty(),"restored chunk generated animals");var files=new DataPack(Path.of("assets/data")).files("spawns");var invalid=new HashMap<String,Object>();invalid.put("biomes",Map.of("UNKNOWN",Map.of()));try{SpawnTable.parse(new JsonObject(invalid,"test",""));throw new AssertionError("invalid table accepted");}catch(com.mineclone.data.JsonException expected){} }
    static void serverRestart() throws Exception {Path root=Files.createTempDirectory("mineclone-herd-restart-");try{long id;try(var s=new ServerSimulationTests.Server(root,"")){var w=s.world();var c=w.getChunk(0,0);var cow=cow(0,8.5f);cow.position.y=100;s.server.mobs().add(cow);s.tick(1);id=cow.id;var save=(SaveManager)s.field("save");var session=(WorldSession)s.field("session");save.saveChunkAsync("sim",session.snapshotChunk(c));save.flushAndAwait();}try(var s=new ServerSimulationTests.Server(root,"")){s.tick(1);check(s.server.mobs().stream().filter(m->m.id==id&&m.type==MobType.COW).count()==1,"server herd identity after restart");}}finally{try(var files=Files.walk(root)){for(var p:files.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}}
}
